class SegTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [0] * (4 * self.n)
        self.build(arr, 1, 0, self.n - 1)
    def build(self, arr, node, l, r):
        if l == r: self.tree[node] = arr[l]; return
        mid = (l + r) // 2
        self.build(arr, 2*node, l, mid)
        self.build(arr, 2*node+1, mid+1, r)
        self.tree[node] = self.tree[2*node] + self.tree[2*node+1]
    def query(self, node, l, r, ql, qr):
        if ql <= l and r <= qr: return self.tree[node]
        if r < ql or l > qr: return 0
        mid = (l + r) // 2
        return self.query(2*node, l, mid, ql, qr) + self.query(2*node+1, mid+1, r, ql, qr)

class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)
    def update(self, i, delta):
        while i <= self.n:
            self.tree[i] += delta
            i += i & -i
    def query(self, i):
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & -i
        return s

